      "title": "悄然抬头，秋天已经来临",
      "caption": "十字架L\n一面手工金花配唐草，一面LOGO点金配唐草雕刻。\n十字架S\n正面手工金花，背面手工雕刻配LOGO点银。\n银牌\n首次推出区别于银饼的银牌。较之于银饼风格更简约，整体更加清爽，厚重感低于银饼。\n正面手工金花，背面游隼雕刻。\n平打宽戒\n首次推出宽版平打戒指，唐草雕刻配手工金花苞。尺码为日码14。\nB戒\n手工双花平打点金戒指，唐草雕刻配手工双金花与LOGO点金。尺码为日码14。",
