      "title": "蛇",
      "caption": "蛇，蜿蜒，灵动而迅速，让人本能地心生敬畏。也许是如神话所言，它原本就是大地的主宰。\n在Belongs的作品元素中，蛇意指“自由前行、长久守护”。\n蛇元素特别套装：\n特制蛇头羽（金绳金牙）x1\n特制金蛇坠x1\n银石子珠x1\n点金绳扣x1\n古董琉璃珠若干",
