      "title": "足迹",
      "caption": "走过的路，少有人回看，但深深足迹，已然留下。\n别人未曾走过的路，总是会多些艰难。\n只是，那些猛烈的情绪，在睡不着的时候给我力量。\n命运之旅，漫长足迹，希望让大家看到不一样的风景。\n银饼\n鹰盾大点金、唐草雕、金日轮、鹰雕。",
