      "caption": "动荡不堪的2021带来太多喧嚣及浮躁。希望崭新的2022重新赐予我们光明、爱、与正能量。\n\n生活本不易，何故言辛苦。无论如何，我们又上路了，迈向新的远方，继续努力为大家带来更多作品。\n\n无论前方有什么，都微笑着面对吧。这也是手作复古银饰赋予的力量。\n\n2022，我们的第四年，你好。\n\n十字架、熔币饼、鹰盾、金银小鹰盾，\n\n2022出发。",
