      "date": "2022年2月11日",
      "title": "无声生长",
      "caption": "手工银饰的迷人之处，外部依托于作品的原创与独特性，而内在植根于追寻自我、拒绝随波逐流的独立态度。\n银饰潮流本是文化，文化的魅力，正是在于有别于他的独一表达。\n千篇一律的复制轻松，不断生长的文化不易。\n时代的弄潮儿，永远追逐着第一波浪头。\n毕竟，每颗种子，都是全然不同的个体。\n本期内容：\n马头坠",
