      "sourceIndex": 480,
      "date": "2022年11月11日",
      "title": "守望",
      "caption": "大海守望风帆，蓝天守望飞鸟，\n父母守望子女，爱人守望爱情，\n………\n这大概是最朴实无华的情感，静静地把你放在心里，任岁月变迁，依然在这里默默的守望。简单的两个字，却是一生的执念，承载着爱与承诺。\n愿大家珍惜属于自己的守望，保守爱与被爱的承诺。\n前路漫漫，我们守望初心，砥砺前行。\n说明：\n*请大家按优先选择顺序编辑编码并发送至官方微信，位数不限。\n*发送单条编码消息之后，请大家耐心等待。请勿连续发送消息反复询问，因为这将造成工作混乱、进展缓慢。\n*完成支付即代表确认购买。\n本期内容：\n1 -> S十字架（守望鹰首点金、背刻羽草）\n2 -> 银饼（守望鹰首点金、背绘唐草、鹰刻印）\n3 -> M十字架（守望鹰首点金、背刻展翅，符节点银）\n4 -> 随形鹰钩坠（守望鹰首点金、背绘唐草、鹰刻印）",
