      "caption": "亲历方知不易，热爱方知珍惜，这一周发售如约而至。愿疫情消散，山河无恙，你我皆安好。\n感谢过去一周大家的关心与问候。\n说明：\n*请大家按优先选择顺序编辑编码并发送至官方微信，位数不限。\n*发送单条编码消息之后，请大家耐心等待。请勿连续发送消息反复询问，因为这将造成工作混乱、进展缓慢。\n*完成支付即代表确认购买。\n本期内容：\n1 -> B戒指（日码11.5码、羽翼点金、画笔羽、符节点银）\n2 -> S饼（符节点玫瑰金、唐草雕刻）\n3 -> 平打戒指（日码16码、符节点金、蛇骨&唐草主题、内刻）\n4 -> 银饼L（远翔鹰点金、写意鹰、草背刻）\n5 ->莫比乌斯镯（M码、手作花点金、鹰刻）",
