      "date": "2022年12月2日",
      "title": "十二月的第一次发售",
      "caption": "人有才、情、趣，花有色、香、喻，人如花，花寓人，这大概就是人们喜欢它的原因吧。\n在Belongs的作品里，花亦以不同的角色出现在每个品类中。\n12月的第一次发售，我们带来新品类宽镯，让“花”给苍白的寒冬，带来一抹暖色。\n一朵花刚开，请予以善良，静待它绽放、盛开。\n说明：\n*请大家按优先选择顺序编辑编码并发送至官方微信，位数不限。\n*发送单条编码消息之后，请大家耐心等待。请勿连续发送消息反复询问，因为这将造成工作混乱、进展缓慢。\n*完成支付即代表确认购买。\n本期内容：\n1 -> 宽镯（花与马主题，金花、鎏金蕊银花、背刻花马）\n2 -> 宽镯（花与蛇主题、金花、点金logo、背刻卷叶蛇）",
