      "title": "腊月",
      "caption": "腊月已至，新年将近，愿岁岁多珍重，一年胜一年。\n说明：\n*请大家按优先选择顺序编辑编码并发送至官方微信，位数不限。\n*发送单条编码消息之后，请大家耐心等待。请勿连续发送消息反复询问，因为这将造成工作混乱、进展缓慢。\n*完成支付即代表确认购买。\n本期内容：\n1 ->银饼（L 、唐草雕伴守望鹰首点金，背刻展翅大鹰）\n2 -> 平打手镯（窄、镯体14cm+开口2.5cm，唐草雕刻，金花、符节点金，内唐草麦穗刻）\n3 -> 初心羽（背刻印—符节）",
