      "sourceIndex": 490,
      "date": "2023年1月13日",
      "title": "记录",
      "caption": "银饰\n于我是纸笔，\n记录脑海里每一格即视的画面，\n记载生命中每一寸饱满的光阴。\n前路迢迢万里，把心交托于你。\n说明：\n*请大家按优先选择顺序编辑编码并发送至官方微信，位数不限。\n*发送单条编码消息之后，请大家耐心等待。请勿连续发送消息反复询问，因为这将造成工作混乱、进展缓慢。\n*完成支付即代表确认购买。\n本期内容：\n1 ->M十字架（符节点金，背刻卷叶）\n2->B戒（日码11，符节点金，鹰首羽翼雕刻）\n3->银饼（符节点金雕刻羽翼，背刻卷叶&羽翼）\n4->莫比乌斯手镯（M码，卷叶主题）\n5->鹰盾（松石镶嵌，远翔鹰点金，背刻鹰隼）\n6->马头坠（金眼，银花金蕊，背刻抽象马）",
