      "date": "2023年2月3日",
      "title": "2月春风",
      "caption": "2月春风逐残霾，暖阳抚嫩芽，晨露慰草木，\n人间青绿可爱。\n而我们也将跟着风的节奏，朝着光的方向，带着希望的感动，继续在艺术的长河里奔流向前。\n本期内容：\n1 -> L十字架（守望鹰首点金、金梗羽毛、满雕刻、于公立2022年制作）\n2 -> 银饼（鹰主题雕刻、点金眼、羽翼点金、背刻浪草、点金逐日鹰刻印）\n3 -> 平打开口戒指（日码16.5、金花、唐草雕刻）\n4 -> 银饼（火焰主题雕刻、羽翼点金、背刻逐火飞鹰）",
      "image": "assets/images/2023/2023-004-99070278d9.jpg",
      "thumb": "assets/thumbs/2023/2023-004-99070278d9.jpg",
      "width": 1080,
      "height": 683,
