      "sourceIndex": 494,
      "date": "2023年2月14日",
      "title": "2.14",
      "caption": "蛇，蜿蜒、灵动而敏捷，\n犀利而坚定的眼神，让人不由心生敬畏。也许如同神话所言，它本是大地的主宰，本能的的守卫着自己的家园。\n永世承诺，无言守护。\n情人节大蛇盾套装\n外形手工敲制。蛇背，爱心框BK字母唐草雕刻、符节点金、金眼；蛇腹，绽放金花眼镜蛇蕊雕刻、刻GURAD字样。唐草钩链配4.0规格丸链。\n购买方式：\n须满足条件获取参与资格\n*拥有一件及以上常规发售的作品；\n*非单身人士；\n*2.14当日佩戴Belongs单品并拍局部照，微信形式分享给Lydia，并留言文字表达购买理由；\n*满足条件后，凭借文字理由的充分度选出获得购买权的玩家；\n*参与截止时间为2月14日下午2:14分；\n*需要时间去仔细阅读每位玩家的购买理由，无法估算确认时间，请耐心等候，结束会以朋友圈形式告知。",
