      "sourceIndex": 496,
      "date": "2023年2月24日",
      "title": "我的春天里藏着一曲雏菊。",
      "caption": "和风吹醒了大地，吹醒了甜睡中的你；\n你伸了个懒腰，抖了抖肩膀上的泥，\n环望四周，此时漫山遍野都是你；\n你向着阳光微笑，你迎着劲风摇曳，\n一丛丛欢愉的精灵，一曲曲浪漫的旋律；\n就这样，你哼着歌，我哼着你；\n就这样，你负责绽放，我负责铭记；\n最后，我把你藏进我的春天，藏进我的心。\n说明：\n*请大家按优先选择顺序编辑编码并发送至官方微信，位数不限。\n*发送单条编码消息之后，请大家耐心等待。请勿连续发送消息反复询问，因为这将造成工作混乱、进展缓慢。\n*完成支付即代表确认购买。\n*发售结束会在朋友圈统一说明，不做一一回复。\n本期内容：\n1 -> K戒（符节金雏菊花、刻Blossom）\n2 -> B戒（符节点金、内B点金、刻Pure）\n3 -> 平打戒指（雏菊点金、刻Vitality）\n4 -> 莫比乌斯戒指（雏菊点金、金钉、刻Eternity）",
