      "date": "2023年3月8日",
      "title": "蝉鸣之音",
      "caption": "女人如蝉，勤劳而美丽，\n在日复一日的生活中默默耕耘，\n在闪闪发光的日子里展露风姿。\n女人如蝉，坚韧而伟大，\n用坚强的意志面对生活的挑战，\n用温暖的光辉照亮晦暗的灵魂。\n让我们把爱倾注给她们， 感恩她们所给予这个世界的智慧与美好，祝愿每一位女性节日快乐。\n说明：\n*只对女性玩家发售。\n*请大家按优先选择顺序编辑编码(左/中/右）并发送至官方微信，位数不限。\n*发送单条编码消息之后，请大家耐心等待。请勿连续发送消息反复询问，因为这将造成工作混乱、进展缓慢。\n*完成支付即代表确认购买。\n*发售结束会在朋友圈统一说明，不做一一回复。\n本期内容：\n左>.蝉形胸针（背刻BLS BEAUTY）\n中>.蝉形胸针（背刻BLS BEAUTY）\n右>.蝉形胸针（背刻BLS BEAUTY）",
