      "caption": "日复一日的创作，源于日复一日的信任与支持。感谢分享生活中的画面与感动，问候与祝福。\n说明：\n*请大家按优先选择顺序编辑编码并发送至官方微信，位数不限。\n*发送单条编码消息之后，请大家耐心等待。请勿连续发送消息反复询问，因为这将造成工作混乱、进展缓慢。\n*完成支付即代表确认购买。\n*发售结束会在朋友圈统一说明，不做一一回复。\n本期内容：\n1 ->M十字（鹰主题）\n2 ->马首（符节点金 金眼）\n3 ->鹰盾（花·草）\n4 ->金饼（B点金，花·草·蛇）",
