      "index": 17,
      "sourceIndex": 505,
      "date": "2023年4月28日",
      "title": "心中的城堡",
      "caption": "人生是一场探索和修行的旅程，过程中充满了许多未知，虽然并不是每一段都完美，但总有收获和感悟。\n我习惯将那些过程中美好的画面整理，存档，安放在心灵深处的城堡内，遇到伤心或困惑就推开城堡的大门，去重温那些善意与温暖，一霎那仿佛那些人就站在我的面前，微笑着与我共情，安慰与鼓励我去坚定的走下去。毫无疑问，这就是Belongs能不断前进的一个重要原因。\n银饰创作，不仅是一种技艺和技能的表现，更是一种对生命和艺术的热爱，同时包含对人生的思考，这是一个漫长的过程。但无论是带着对生命的理解去创作，还是将饰品赋予生命的意义，我们都在不断地探索和实践。也正是这种对生命的热爱，对美好的记录，让我们变得更加勇敢、坚定和独立。\n愿将这一份温度留存心间，在迷茫的时候予以光明与信念。\n说明：\n*请大家按优先选择顺序编辑编码并发送至官方微信，位数不限。\n*发送单条编码消息之后，请大家耐心等待。请勿连续发送消息反复询问，因为这将造成工作混乱、进展缓慢。\n*完成支付即代表确认购买。\n*为尽快通知结果，售罄后会在朋友圈统一说明，不做一一回复。\n*为避免信息遗漏，非当日发售作品的问题请在发售结束后咨询。\n本期内容\n1*即兴蛇头环（主题“Guard”的多功能性作品）\n2*金银马吊坠 （金银结合的马，搭配唐草，缰绳）\n3*马首（装扮金饰）\n4*莫比乌斯镯 *M（予翼翱翔）\n5*平打镯*M（连绵的细唐草，金花与符节。*镯体约15 开口约2.5）\n6*狗牌（蛇绕金镶宝石，光照牡丹花丛）\n7*方牌套装（唐草与鹰的满雕，守望光明的画面。*链净长60cm）",
      "image": "assets/images/2023/2023-017-381a441f08.jpg",
      "thumb": "assets/thumbs/2023/2023-017-381a441f08.jpg",
      "width": 1080,
      "height": 830,
      "largeWidth": 1080,
      "largeHeight": 830,
      "thumbWidth": 520,
