      "date": "2023年10月13日",
      "title": "收获",
      "caption": "作品内容：\n1*马首（我在天空中奔跑，一片片云浪遮盖住我的身体，此时它们和我是一体的。我望向远处，正午的阳光的确很耀眼，鹰追逐着光往高处越飞越远…）\n2*鹰盾（我把羽毛做成项链戴在脖颈上，今天我将作为信使，带着收获的麦穗去传达福音，传达爱）\n3*平打手镯（一对恪守初心的羽翼，守护着沙漏，守护着最初的梦。时间验证了一切，鹰幻做使者传达福音，送来了收获的麦穗。#镯体≈14.5，开口≈3cm）\n4*缰绳戒指（金与银，十字浮出与镂空，神圣的样子。#港码≈17码）\n5*S十字（秋日的麦穗在十字的画框里起舞，收获的喜悦洋溢在它的脸上）",
      "image": "assets/images/2023/2023-032-539243d710.jpg",
      "thumb": "assets/thumbs/2023/2023-032-539243d710.jpg",
