      "title": "Merry Christma！",
      "caption": "Through hill and valley every breezeHad sunk to rest with folded wings:Keen was the air, but could not freeze,Nor check, the music of the strings;So stout and hardy were the bandThat scraped the chords with strenuous hand.\nAnd who but listened?…\n\"Merry Christmas\" wished to all.\n穿过山谷的每一阵微风下沉收起翅膀：风是那么锋利，但永不冷漠，也不核对，弦音声声；一层层又如此的强烈刚强，用热烈的手摩擦着弦柱。这一刻是谁在倾听？\n祝福大家：❄️圣诞快乐呀❄️\n——William Wordsworth 《The Minstrels》",
